def best_sum_of_three(numbers):
    if len(numbers) < 3:
        return None
    window = sum(numbers[:3])
    best = window
    for i in range(3, len(numbers)):
        window += numbers[i] - numbers[i - 3]
        best = max(best, window)
    return best

