def fewest_coins_with_3_5(amount):
    big = amount + 1
    best = [0] + [big] * amount
    for x in range(1, amount + 1):
        for coin in (3, 5):
            if coin <= x and best[x - coin] + 1 < best[x]:
                best[x] = best[x - coin] + 1
    return best[amount] if best[amount] < big else -1

